(41471,	3853,	301,	'The truth will offend people\r\nIt is a privilege to serve\r\n.',	'2017-10-15 00:22:12',	'2017-10-15 00:22:12'),
(41472,	3853,	302,	'.',	'2017-10-15 00:22:12',	'2017-10-15 00:22:12'),
(41473,	3853,	303,	'.',	'2017-10-15 00:22:12',	'2017-10-15 00:22:12'),
(41474,	3853,	316,	'Forgiveness is mandatory to be saved.\r\nForgive as Christ forgave us.\r\n.',	'2017-10-15 00:30:54',	'2017-10-15 00:30:54'),
(41475,	3853,	317,	'Forgiveness',	'2017-10-15 00:30:54',	'2017-10-15 00:30:54'),
(41476,	3853,	318,	'.',	'2017-10-15 00:30:54',	'2017-10-15 00:30:54'),
