(41950,	3892,	5898,	'Just to know if i have any question of my position, to ask for forgiveness and believe that he has forgiven me and his blood is covering me.',	'2017-10-26 20:21:27',	'2017-10-26 20:21:27'),
(41951,	3892,	5911,	'We must have the right understanding of the lines of Authority.\r\nWe must submit to the leaders God has placed over us in authority.\r\nPrayers show our desires for God and fasting illustrates our self denial.',	'2017-10-26 21:20:00',	'2017-10-26 21:20:00'),
