(41960,	2000,	331,	'Deal with the offense while it is early, do not let its roots grow in your heart.\r\nDo not avoid offenses - deal with it.\r\nJesus Christ died on the cross for your unfulfilled revenge.',	'2017-10-27 06:24:23',	'2017-10-27 06:24:23'),
