  KEY `temp_users_state_id_index` (`state_id`),
  KEY `temp_users_invited_by_user_id_index` (`invited_by_user_id`),
  KEY `temp_users_invitation_id_index` (`invitation_id`),
  KEY `temp_users_email_index` (`email`),
  KEY `temp_users_username_index` (`username`),
  KEY `temp_users_church_id_foreign` (`church_id`),
  CONSTRAINT `temp_users_church_id_foreign` FOREIGN KEY (`church_id`) REFERENCES `churches` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `temp_users_country_id_foreign` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `temp_users_invitation_id_foreign` FOREIGN KEY (`invitation_id`) REFERENCES `user_invitation` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `temp_users_invited_by_user_id_foreign` FOREIGN KEY (`invited_by_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `temp_users_state_id_foreign` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `timezones`;
CREATE TABLE `timezones` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `country_id` bigint unsigned NOT NULL,
  `identifier` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `timezone` varchar(191) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `display_order` int NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `timezones_country_id_foreign` (`country_id`),
  CONSTRAINT `timezones_country_id_foreign` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `user_credit_transactions`;
CREATE TABLE `user_credit_transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `credit_to_userid` bigint unsigned DEFAULT NULL,
  `credit_from_userid` bigint unsigned DEFAULT NULL,
  `transaction_type` enum('credit','debit') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'credit',
  `type` enum('course_transfer','user_transfer','admin_transfer','yearly_transfer','initial_transfer') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'initial_transfer',
  `amount` bigint unsigned NOT NULL,
  `balance` bigint unsigned NOT NULL,
  `is_admin_involved` enum('yes','no') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'no',
  `description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `course_id` bigint unsigned DEFAULT NULL,
  `lesson_id` bigint unsigned DEFAULT NULL,
  `student_progress_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_credit_transactions_user_id_foreign` (`user_id`),
  KEY `user_credit_transactions_credit_from_userid_foreign` (`credit_from_userid`),
  KEY `user_credit_transactions_course_id_foreign` (`course_id`),
  KEY `user_credit_transactions_lesson_id_foreign` (`lesson_id`),
  KEY `user_credit_transactions_student_progress_id_foreign` (`student_progress_id`),
  KEY `user_credit_transactions_credit_to_userid_foreign` (`credit_to_userid`),
  CONSTRAINT `user_credit_transactions_course_id_foreign` FOREIGN KEY (`course_id`) REFERENCES `courses` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `user_credit_transactions_credit_from_userid_foreign` FOREIGN KEY (`credit_from_userid`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `user_credit_transactions_credit_to_userid_foreign` FOREIGN KEY (`credit_to_userid`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `user_credit_transactions_lesson_id_foreign` FOREIGN KEY (`lesson_id`) REFERENCES `lessons` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `user_credit_transactions_student_progress_id_foreign` FOREIGN KEY (`student_progress_id`) REFERENCES `student_progress` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `user_credit_transactions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


DROP TABLE IF EXISTS `user_dashboard_preferences`;
CREATE TABLE `user_dashboard_preferences` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
